        lfs_block_t block_count = lfs->cfg->block_count;
        lfs_block_t scan_start = lfs->free.begin + lfs->free.off;
        lfs_block_t scan_end = lfs->free.begin + lfs->free.size;

        // Wrap around if needed
        if (scan_start >= block_count) {
            scan_start -= block_count;
        }
        if (scan_end > block_count) {
            scan_end = block_count;
        }

        // Scan for free blocks
        lfs_block_t free_count = 0;
        for (lfs_block_t b = scan_start; b < scan_end; b++) {
            int err = lfs->cfg->read(lfs->cfg, b, 0, lfs->free.buffer, lfs->cfg->block_size);
            if (err) {
                return err;
            }

            // Check if block is free (all bytes 0xFF)
            bool is_free = true;
            for (std::size_t i = 0; i < lfs->cfg->block_size; i++) {
                if (lfs->free.buffer[i] != 0xFF) {
                    is_free = false;
                    break;
                }
            }

            if (is_free) {
                free_count++;
            } else {
                // Found a used block, reset free count
                free_count = 0;
            }

            // If we found enough free blocks, update lookahead
            if (free_count == lfs->cfg->lookahead_size / 8) {
                lfs->free.begin = b - free_count + 1;
                lfs->free.off = 0;
                lfs->free.size = free_count;
                break;
            }
        }

        // If we didn't find enough free blocks, check if we have any
        if (lfs->free.off == lfs->free.size) {
            // No free blocks found
            return LFS_ERR_NOSPC;
        }
    }

    // Find the next free block in the lookahead buffer
    while (true) {
        // Check if current bit is set
        if (!(lfs->free.buffer[lfs->free.off / 8] & (1 << (lfs->free.off % 8)))) {
            // Found a free block, allocate it
            *block = lfs->free.begin + lfs->free.off;

            // Mark block as used in lookahead buffer
            lfs->free.buffer[lfs->free.off / 8] |= 1 << (lfs->free.off % 8);

            // Move to next block
            lfs->free.off++;

            // Update filesystem's wear count
            lfs->wear[*block]++;

            return 0;
        }

        // Move to next block
        lfs->free.off++;

        // If we've reached the end of the lookahead buffer, scan for more
        if (lfs->free.off == lfs->free.size) {
            break;
        }
    }

    // If we get here, we need to scan for more free blocks
    // This should be handled by the initial check, but just in case
    return LFS_ERR_NOSPC;
    // END_CODE

